//! Phase-0 oracle: the indexed JSON store must read a canonical
//! `catalog.json` written by the Python `LocalCatalogRepository` and rewrite
//! it byte-for-byte.
//!
//! The fixture is generated by `src/lake/tests/oracle/generate.py`.

use lake_catalog::{CatalogRepository, CoverageQuery, CoverageStatus, JsonCatalogStore};
use lake_contracts::{AssetClass, DataType, Date};

const ORACLE: &str = include_str!("oracle/catalog_v1.json");

#[test]
fn oracle_catalog_loads_into_the_index() {
    let directory = tempfile::tempdir().expect("tempdir");
    let path = directory.path().join("catalog.json");
    std::fs::write(&path, ORACLE).expect("write oracle");
    let store = JsonCatalogStore::open(&path).expect("open store");
    let records = store.list(&CoverageQuery::default()).expect("list");
    assert_eq!(records.len(), 5);
    let keys: Vec<String> = records
        .iter()
        .map(|record| {
            format!(
                "{}|{}|{}|{}",
                record.asset_class.value(),
                record.data_type.value(),
                record.symbol,
                record.session_date.isoformat()
            )
        })
        .collect();
    assert_eq!(
        keys,
        vec![
            "crypto|quote|BTC/USD|2024-01-06",
            "equity|quote|AAPL|2024-01-18",
            "equity|quote|SPY|2024-01-22",
            "equity|trade|AAPL|2024-01-18",
            "equity|trade|SPY|2024-01-19",
        ]
    );
    let aapl = store
        .get(
            AssetClass::Equity,
            DataType::Trade,
            None,
            "AAPL",
            Date::from_ymd(2024, 1, 18).expect("date"),
        )
        .expect("get")
        .expect("present");
    assert_eq!(aapl.status, CoverageStatus::Complete);
    assert_eq!(aapl.row_count, 120);
    assert_eq!(aapl.byte_size, 4567);
    assert_eq!(
        aapl.checksum.as_deref(),
        Some("abababababababababababababababababababababababababababababababab")
    );
    let spy = store
        .get(
            AssetClass::Equity,
            DataType::Trade,
            None,
            "SPY",
            Date::from_ymd(2024, 1, 19).expect("date"),
        )
        .expect("get")
        .expect("present");
    assert_eq!(spy.status, CoverageStatus::Error);
    assert_eq!(spy.object_path, None);
    assert!(spy
        .error_message
        .as_deref()
        .expect("message")
        .contains("AlpacaHTTPError"));
}

#[test]
fn rewriting_the_oracle_catalog_is_byte_identical() {
    let directory = tempfile::tempdir().expect("tempdir");
    let path = directory.path().join("catalog.json");
    std::fs::write(&path, ORACLE).expect("write oracle");
    let store = JsonCatalogStore::open(&path).expect("open store");
    let records = store.list(&CoverageQuery::default()).expect("list");
    for record in &records {
        store.upsert(record).expect("upsert");
    }
    let rewritten = std::fs::read_to_string(&path).expect("read rewritten");
    assert_eq!(rewritten, ORACLE);
    assert!(rewritten.ends_with('\n'));
}

#[test]
fn outdated_terminal_bars_without_provenance_are_rejected() {
    let directory = tempfile::tempdir().expect("tempdir");
    let path = directory.path().join("catalog.json");
    let mut document: serde_json::Value = serde_json::from_str(ORACLE).expect("JSON");
    document["coverage"][0]["data_type"] = "bars".into();
    document["coverage"][0]["interval"] = "1min".into();
    std::fs::write(&path, serde_json::to_vec(&document).expect("encode")).expect("write");
    let error = match JsonCatalogStore::open(&path) {
        Ok(_) => panic!("outdated catalog accepted"),
        Err(error) => error,
    };
    assert!(error.to_string().contains("provenance is required"));
}
